// SmartHelmet/Software/src/components/SurveillanceTunnelMap.jsx

import { useMemo } from 'react';
import { TUNNEL_GRAPH, THRESHOLDS } from '../utils/constants';
import { runDijkstra } from '../services/api';
import '../styles/SurveillanceTunnelMap.css';

/* ═════════════════════════════════════════════════════════════════════
   SURVEILLANCE TUNNEL MAP CONSTANTS
   ViewBox: 0 0 960 540
   ═════════════════════════════════════════════════════════════════════ */

const NODES = {
  'Entrance':       { x: 120, y: 280 },
  'Main Junction':  { x: 340, y: 280 },
  'West Junction':  { x: 540, y: 200 },
  'East Junction':  { x: 680, y: 320 },
  'Zone A':         { x: 300, y: 130 },
  'Zone B':         { x: 740, y: 140 },
  'Zone C':         { x: 820, y: 340 },
};

/** Primary connection edges matching TUNNEL_GRAPH */
const EDGES = [
  { from: 'Entrance',      to: 'Main Junction',  d: 'M 120,280 C 190,270 270,290 340,280' },
  { from: 'Main Junction', to: 'West Junction',   d: 'M 340,280 C 400,280 460,200 540,200' },
  { from: 'Main Junction', to: 'East Junction',   d: 'M 340,280 C 440,280 560,320 680,320' },
  { from: 'West Junction', to: 'Zone A',          d: 'M 540,200 C 460,200 380,140 300,130' },
  { from: 'West Junction', to: 'Zone B',          d: 'M 540,200 C 600,200 660,140 740,140' },
  { from: 'East Junction', to: 'Zone B',          d: 'M 680,320 C 720,280 720,180 740,140' },
  { from: 'East Junction', to: 'Zone C',          d: 'M 680,320 C 730,320 770,340 820,340' },
].map((e) => ({ ...e, key: [e.from, e.to].sort().join('|') }));

/** Secondary framing tunnel galleries for organic mine depth */
const AMBIENT_GALLERIES = [
  'M 300,130 C 440,80 620,80 740,140',
  'M 120,280 C 180,390 340,430 540,430 C 680,430 760,410 820,340',
  'M 340,280 C 320,200 300,160 300,130',
  'M 540,200 C 560,300 600,340 680,320',
  'M 740,140 C 800,140 860,220 820,340',
  'M 300,130 C 220,140 160,200 120,280',
  'M 540,430 C 600,470 700,460 760,410',
  'M 180,390 C 240,460 380,470 540,430',
];

/** Background zone letter watermarks */
const ZONE_LETTERS = [
  { letter: 'A', x: 260, y: 100 },
  { letter: 'B', x: 740, y: 90 },
  { letter: 'C', x: 860, y: 390 },
  { letter: 'D', x: 540, y: 470 },
];

function getHazardInfo(reading, status) {
  if (status !== 'warning' && status !== 'emergency') return null;

  let label = 'HAZARD ZONE';
  if (reading?.gas_level >= THRESHOLDS.gas_level.warning) {
    label = 'GAS HAZARD';
  } else if (reading?.temperature >= THRESHOLDS.temperature.warning) {
    label = 'HEAT HAZARD';
  } else if (reading?.force >= THRESHOLDS.force.warning) {
    label = 'IMPACT ALERT';
  } else if (reading?.heart_rate > 0 && 
    (reading.heart_rate <= THRESHOLDS.heart_rate.warningLow || reading.heart_rate >= THRESHOLDS.heart_rate.warningHigh)) {
    label = 'VITAL ALERT';
  }

  return {
    label,
    isEmergency: status === 'emergency',
  };
}

export default function SurveillanceTunnelMap({ worker, reading, zone, status }) {
  const activeZone = zone || 'Entrance';
  const workerPos = NODES[activeZone] || NODES['Entrance'];
  const rssi = reading?.rssi ?? null;
  const workerName = worker?.name || worker?.worker_id || 'Worker';

  const isDanger = status === 'warning' || status === 'emergency';
  const isEmergency = status === 'emergency';
  const hazardInfo = getHazardInfo(reading, status);

  // Derive shortest rescue route using Dijkstra when worker is in danger
  const rescueRouteNodes = useMemo(() => {
    if (!isDanger) return [];
    const target = NODES[activeZone] ? activeZone : 'Zone B';
    const path = runDijkstra(TUNNEL_GRAPH, 'Entrance', target);
    return path.length > 0 ? path : ['Entrance', 'Main Junction', 'East Junction', 'Zone C'];
  }, [isDanger, activeZone]);

  // Set of edge keys on the active rescue route
  const rescueEdgeKeys = useMemo(() => {
    const keys = new Set();
    for (let i = 0; i < rescueRouteNodes.length - 1; i++) {
      keys.add([rescueRouteNodes[i], rescueRouteNodes[i + 1]].sort().join('|'));
    }
    return keys;
  }, [rescueRouteNodes]);

  return (
    <div className="surveillance-map-card">
      {/* ── Header ─────────────────────────────────────────────── */}
      <div className="surveillance-map-header">
        <div className="stm-header-left">
          <span className="surveillance-map-title">Tunnel Surveillance Map</span>
          <span className="surveillance-map-subtitle">Live position and rescue route guidance</span>
        </div>

        <div className={`stm-status-badge ${status || 'normal'}`}>
          <span className={`stm-status-dot ${status || 'normal'}`} />
          {isEmergency ? 'EMERGENCY' : isDanger ? 'WARNING' : 'ALL CLEAR'}
        </div>
      </div>

      {/* ── SVG Canvas Scene ───────────────────────────────────── */}
      <div className="surveillance-map-canvas">
        {!reading && !zone && (
          <div className="stm-awaiting-overlay">
            <div className="stm-awaiting-icon">📡</div>
            <div className="stm-awaiting-text">Awaiting location data</div>
          </div>
        )}

        <svg viewBox="0 0 960 540" preserveAspectRatio="xMidYMid meet">
          <defs>
            {/* Blueprint Grid Pattern */}
            <pattern id="stm-blueprint-grid" width="40" height="40" patternUnits="userSpaceOnUse">
              <path d="M 40 0 L 0 0 0 40" fill="none" stroke="rgba(0, 180, 255, 0.05)" strokeWidth="0.8" />
              <circle cx="0" cy="0" r="1" fill="rgba(0, 180, 255, 0.15)" />
            </pattern>

            {/* Tunnel Glow Filter */}
            <filter id="tunnel-glow" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur in="SourceGraphic" stdDeviation="6" result="blur" />
              <feMerge>
                <feMergeNode in="blur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>

            {/* Rescue Route Glow Filter */}
            <filter id="rescue-glow" x="-30%" y="-30%" width="160%" height="160%">
              <feGaussianBlur in="SourceGraphic" stdDeviation="8" result="blur1" />
              <feGaussianBlur in="SourceGraphic" stdDeviation="3" result="blur2" />
              <feMerge>
                <feMergeNode in="blur1" />
                <feMergeNode in="blur2" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>

            {/* Worker Marker Glow Filter */}
            <filter id="worker-glow" x="-50%" y="-50%" width="200%" height="200%">
              <feGaussianBlur in="SourceGraphic" stdDeviation="8" result="blur" />
              <feMerge>
                <feMergeNode in="blur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>

            {/* Hazard Radial Gradient */}
            <radialGradient id="hazard-gradient" cx="50%" cy="50%" r="50%">
              <stop offset="0%" stopColor={isEmergency ? 'rgba(239, 68, 68, 0.35)' : 'rgba(249, 115, 22, 0.25)'} />
              <stop offset="70%" stopColor={isEmergency ? 'rgba(239, 68, 68, 0.12)' : 'rgba(249, 115, 22, 0.08)'} />
              <stop offset="100%" stopColor="transparent" />
            </radialGradient>
          </defs>

          {/* ── LAYER 1: Background & Blueprint Grid ────────── */}
          <rect width="960" height="540" fill="#040714" />
          <rect width="960" height="540" fill="url(#stm-blueprint-grid)" />

          {/* Vignette Shadow */}
          <radialGradient id="vignette" cx="50%" cy="50%" r="70%">
            <stop offset="60%" stopColor="transparent" />
            <stop offset="100%" stopColor="rgba(0, 0, 0, 0.75)" />
          </radialGradient>
          <rect width="960" height="540" fill="url(#vignette)" />

          {/* ── LAYER 2: Zone Letter Watermarks ──────────────── */}
          {ZONE_LETTERS.map((z) => (
            <g key={z.letter}>
              <rect
                x={z.x - 22}
                y={z.y - 22}
                width="44"
                height="44"
                rx="10"
                fill="none"
                stroke="rgba(0, 180, 255, 0.12)"
                strokeWidth="1.5"
              />
              <text
                x={z.x}
                y={z.y + 1}
                fill="rgba(0, 180, 255, 0.18)"
                fontSize="24"
                fontWeight="800"
                fontFamily="'Plus Jakarta Sans', sans-serif"
                textAnchor="middle"
                dominantBaseline="middle"
              >
                {z.letter}
              </text>
            </g>
          ))}

          {/* ── LAYER 3: Ambient framing galleries ────────────── */}
          <g strokeLinecap="round" opacity="0.35">
            {AMBIENT_GALLERIES.map((d, i) => (
              <path
                key={`ambient-${i}`}
                d={d}
                fill="none"
                stroke="rgba(0, 140, 220, 0.25)"
                strokeWidth="4"
              />
            ))}
          </g>

          {/* ── LAYER 4: Base Tunnel Network System ───────────── */}
          {/* Outer Ambient Glow Stroke */}
          <g filter="url(#tunnel-glow)" opacity="0.7">
            {EDGES.map((e) => (
              <path
                key={`glow-${e.key}`}
                d={e.d}
                fill="none"
                stroke="rgba(0, 212, 255, 0.35)"
                strokeWidth="14"
                strokeLinecap="round"
              />
            ))}
          </g>

          {/* Tunnel Wall Stroke */}
          <g>
            {EDGES.map((e) => (
              <path
                key={`wall-${e.key}`}
                d={e.d}
                fill="none"
                stroke="rgba(0, 150, 230, 0.45)"
                strokeWidth="7"
                strokeLinecap="round"
              />
            ))}
          </g>

          {/* Bright Core Line */}
          <g>
            {EDGES.map((e) => (
              <path
                key={`core-${e.key}`}
                d={e.d}
                fill="none"
                stroke="#00d4ff"
                strokeWidth="2.2"
                strokeLinecap="round"
              />
            ))}
          </g>

          {/* ── LAYER 5: Active Rescue Route (ONLY in Danger) ── */}
          {isDanger && (
            <g filter="url(#rescue-glow)">
              {/* Outer Vibrant Green Glow */}
              {EDGES.filter((e) => rescueEdgeKeys.has(e.key)).map((e) => (
                <path
                  key={`rescue-glow-${e.key}`}
                  d={e.d}
                  fill="none"
                  stroke={isEmergency ? 'rgba(34, 197, 94, 0.65)' : 'rgba(34, 197, 94, 0.45)'}
                  strokeWidth="18"
                  strokeLinecap="round"
                />
              ))}

              {/* Solid Green Rescue Tube */}
              {EDGES.filter((e) => rescueEdgeKeys.has(e.key)).map((e) => (
                <path
                  key={`rescue-tube-${e.key}`}
                  d={e.d}
                  fill="none"
                  stroke="#22c55e"
                  strokeWidth="7"
                  strokeLinecap="round"
                />
              ))}

              {/* Bright Core White Line */}
              {EDGES.filter((e) => rescueEdgeKeys.has(e.key)).map((e) => (
                <path
                  key={`rescue-core-${e.key}`}
                  d={e.d}
                  fill="none"
                  stroke="#ffffff"
                  strokeWidth="2.5"
                  strokeLinecap="round"
                />
              ))}

              {/* Animated Directional Dash Flow */}
              {EDGES.filter((e) => rescueEdgeKeys.has(e.key)).map((e) => (
                <path
                  key={`rescue-dash-${e.key}`}
                  className="stm-rescue-dash-flow"
                  d={e.d}
                  fill="none"
                  stroke="rgba(255, 255, 255, 0.8)"
                  strokeWidth="2.5"
                  strokeLinecap="round"
                  strokeDasharray="10 22"
                />
              ))}
            </g>
          )}

          {/* ── LAYER 6: Hazard Overlay (ONLY in Danger) ──────── */}
          {isDanger && hazardInfo && (
            <g className="stm-hazard-contour-pulse">
              {/* Organic contour around hazard zone (Zone C / East area) */}
              <path
                d="M 640,210 C 700,170 820,170 870,230 C 910,290 870,410 770,420 C 670,420 620,330 640,210 Z"
                fill="url(#hazard-gradient)"
                stroke={isEmergency ? '#ef4444' : '#f97316'}
                strokeWidth="2.2"
                strokeDasharray="8 5"
              />

              {/* Hazard Badge Icon & Text */}
              <g transform="translate(750, 270)">
                <rect
                  x="-65"
                  y="-42"
                  width="130"
                  height="44"
                  rx="10"
                  fill="rgba(4, 7, 20, 0.85)"
                  stroke={isEmergency ? '#ef4444' : '#f97316'}
                  strokeWidth="1.5"
                />
                {/* Warning Triangle Icon */}
                <path
                  d="M 0,-30 L 10,-12 L -10,-12 Z"
                  fill={isEmergency ? '#ef4444' : '#f97316'}
                />
                <text
                  x="0"
                  y="-18"
                  textAnchor="middle"
                  fill="#FFFFFF"
                  fontSize="9"
                  fontWeight="800"
                >
                  !
                </text>

                <text
                  x="0"
                  y="-8"
                  textAnchor="middle"
                  fill={isEmergency ? '#ef4444' : '#f97316'}
                  fontSize="10"
                  fontWeight="800"
                  fontFamily="'Plus Jakarta Sans', sans-serif"
                  letterSpacing="0.08em"
                >
                  {hazardInfo.label}
                </text>
              </g>
            </g>
          )}

          {/* ── LAYER 7: Node / Junction Points ──────────────── */}
          {Object.entries(NODES).map(([nodeName, pos]) => {
            const isRescueNode = rescueRouteNodes.includes(nodeName);
            const isWorkerNode = nodeName === activeZone;

            return (
              <g key={nodeName} transform={`translate(${pos.x}, ${pos.y})`}>
                {/* Outer Glow Ring */}
                <circle
                  r={isWorkerNode ? 12 : isRescueNode ? 10 : 8}
                  fill="rgba(4, 7, 20, 0.9)"
                  stroke={isWorkerNode ? '#00d4ff' : isRescueNode ? '#22c55e' : 'rgba(0, 180, 255, 0.5)'}
                  strokeWidth={isWorkerNode ? 2.5 : isRescueNode ? 2 : 1.5}
                />

                {/* Inner Dot */}
                <circle
                  r={isWorkerNode ? 5 : isRescueNode ? 4 : 3}
                  fill={isWorkerNode ? '#00d4ff' : isRescueNode ? '#22c55e' : '#00d4ff'}
                  className={isRescueNode && !isWorkerNode ? 'stm-rescue-pulse-node' : ''}
                />

                {/* Node Label */}
                {nodeName !== 'Entrance' && !isWorkerNode && (
                  <text
                    y="22"
                    textAnchor="middle"
                    fill="rgba(160, 174, 192, 0.75)"
                    fontSize="9"
                    fontWeight="600"
                    fontFamily="'Plus Jakarta Sans', sans-serif"
                  >
                    {nodeName}
                  </text>
                )}
              </g>
            );
          })}

          {/* ── LAYER 8: Entrance Marker Badge ───────────────── */}
          <g transform={`translate(${NODES.Entrance.x}, ${NODES.Entrance.y})`}>
            {/* Entrance Portal Arch Icon */}
            <g transform="translate(-45, -18)">
              <rect
                x="0"
                y="0"
                width="90"
                height="36"
                rx="10"
                fill="rgba(4, 8, 23, 0.85)"
                stroke="rgba(0, 212, 255, 0.4)"
                strokeWidth="1.5"
              />
              <path
                d="M 16,25 V 14 A 9,9 0 0 1 34,14 V 25"
                fill="none"
                stroke="#00d4ff"
                strokeWidth="2"
              />
              <text
                x="56"
                y="22"
                textAnchor="middle"
                fill="#00d4ff"
                fontSize="9"
                fontWeight="800"
                fontFamily="'Plus Jakarta Sans', sans-serif"
                letterSpacing="0.08em"
              >
                ENTRANCE
              </text>
            </g>
          </g>

          {/* ── LAYER 9: Live Worker Marker ───────────────────── */}
          <g transform={`translate(${workerPos.x}, ${workerPos.y})`} className="stm-worker-marker">
            {/* Outer Expanding Pulsing Ring */}
            <circle
              className="stm-worker-pulse-outer"
              r="24"
              fill="none"
              stroke="#00d4ff"
              strokeWidth="2"
            />

            {/* Inner Core Pulsing Halo */}
            <g className="stm-worker-pulse-inner" filter="url(#worker-glow)">
              <circle
                r="18"
                fill="rgba(0, 212, 255, 0.25)"
                stroke="#00d4ff"
                strokeWidth="2.5"
              />
              <circle r="12" fill="#040714" stroke="#00d4ff" strokeWidth="2" />

              {/* Worker Person Glyph */}
              <circle cx="0" cy="-4" r="3" fill="#00d4ff" />
              <path
                d="M -5,5 C -5,1 -3,0 0,0 C 3,0 5,1 5,5 Z"
                fill="#00d4ff"
              />
            </g>

            {/* Worker Label Badge Pill */}
            <g transform="translate(0, 32)">
              <rect
                x="-42"
                y="-11"
                width="84"
                height="22"
                rx="11"
                fill="rgba(4, 7, 20, 0.9)"
                stroke="#00d4ff"
                strokeWidth="1.5"
              />
              <text
                x="0"
                y="4"
                textAnchor="middle"
                fill="#FFFFFF"
                fontSize="10"
                fontWeight="700"
                fontFamily="'JetBrains Mono', 'Fira Code', monospace"
              >
                {workerName}
              </text>
            </g>
          </g>

          {/* ── LAYER 10: North Arrow Compass ────────────────── */}
          <g transform="translate(48, 48)">
            <circle
              r="18"
              fill="rgba(4, 7, 20, 0.7)"
              stroke="rgba(0, 180, 255, 0.25)"
              strokeWidth="1.2"
            />
            <path d="M 0,-12 L 4,-3 L 0,-6 L -4,-3 Z" fill="#00d4ff" />
            <path d="M 0,12 L 4,3 L 0,6 L -4,3 Z" fill="rgba(160, 174, 192, 0.4)" />
            <text
              x="0"
              y="-15"
              textAnchor="middle"
              fill="#00d4ff"
              fontSize="9"
              fontWeight="800"
              fontFamily="'Plus Jakarta Sans', sans-serif"
            >
              N
            </text>
          </g>

          {/* ── LAYER 11: Scale Ruler Line ───────────────────── */}
          <g transform="translate(48, 495)">
            <line x1="0" y1="0" x2="120" y2="0" stroke="rgba(160, 174, 192, 0.4)" strokeWidth="1.5" />
            <line x1="0" y1="-4" x2="0" y2="4" stroke="rgba(160, 174, 192, 0.4)" strokeWidth="1.5" />
            <line x1="40" y1="-3" x2="40" y2="3" stroke="rgba(160, 174, 192, 0.3)" strokeWidth="1" />
            <line x1="80" y1="-3" x2="80" y2="3" stroke="rgba(160, 174, 192, 0.3)" strokeWidth="1" />
            <line x1="120" y1="-4" x2="120" y2="4" stroke="rgba(160, 174, 192, 0.4)" strokeWidth="1.5" />
            <text x="0" y="14" fill="rgba(160, 174, 192, 0.6)" fontSize="9" fontFamily="'JetBrains Mono', monospace">0</text>
            <text x="40" y="14" fill="rgba(160, 174, 192, 0.6)" fontSize="9" fontFamily="'JetBrains Mono', monospace" textAnchor="middle">50</text>
            <text x="80" y="14" fill="rgba(160, 174, 192, 0.6)" fontSize="9" fontFamily="'JetBrains Mono', monospace" textAnchor="middle">100</text>
            <text x="120" y="14" fill="rgba(160, 174, 192, 0.6)" fontSize="9" fontFamily="'JetBrains Mono', monospace" textAnchor="end">150m</text>
          </g>
        </svg>
      </div>

      {/* ── Footer HUD ─────────────────────────────────────────── */}
      <div className="surveillance-map-footer">
        <div className="surveillance-map-legend">
          <span className="stm-legend-chip">
            <span className="stm-legend-swatch tunnel" />
            Tunnel Network
          </span>
          <span className="stm-legend-chip">
            <span className="stm-legend-swatch worker" />
            Worker Position
          </span>
          <span className="stm-legend-chip">
            <span className="stm-legend-swatch rescue" />
            Rescue Path (Danger Only)
          </span>
          <span className="stm-legend-chip">
            <span className="stm-legend-swatch hazard" />
            Hazard Zone
          </span>
        </div>

        <div className="surveillance-map-summary">
          <div className="stm-summary-item">
            <span className="stm-summary-label">Current Zone</span>
            <span className="stm-summary-value zone">{activeZone}</span>
          </div>
          <div className="stm-summary-item">
            <span className="stm-summary-label">Signal RSSI</span>
            <span className="stm-summary-value rssi">
              {rssi != null ? `${rssi} dBm` : '—'}
            </span>
          </div>
          <span className="stm-summary-note">Estimated by beacon RSSI</span>
        </div>
      </div>
    </div>
  );
}
